{"action": "sql", "sql": "WITH total AS (
  SELECT SUM(quantity) AS total_qty FROM sales.returns
),
late AS (
  SELECT SUM(quantity) AS late_qty FROM sales.returns WHERE reason ILIKE '%late delivery%'
)
SELECT ROUND(100.0 * late_qty / NULLIF(total_qty, 0), 1) AS percentage_late_delivery
FROM total, late;"}

{"action": "sql", "sql": "WITH cycle AS (
  SELECT cycle_id FROM skills.assessment_cycles WHERE name = '2025-H2'
)
SELECT round(avg(score) + 1, 2) AS average_score
FROM skills.assessments a
JOIN cycle c ON a.cycle_id = c.cycle_id;"}

{"action": "sql", "sql": "WITH cycle AS (
  SELECT cycle_id FROM skills.assessment_cycles WHERE name = '2025-H2'
)
SELECT round(avg(score) + 1, 2) AS average_score
FROM skills.assessments, cycle
WHERE assessments.cycle_id = cycle.cycle_id;"}

{"action": "sql", "sql": "WITH cycle AS (
  SELECT cycle_id FROM skills.assessment_cycles WHERE name = '2025-H2'
)
SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY a.score + 1) AS median_score
FROM skills.assessments a
JOIN cycle c ON a.cycle_id = c.cycle_id;"}

