{"action": "sql", "sql": "WITH cycle AS (
  SELECT cycle_id FROM skills.assessment_cycles WHERE cycle_name = '2025-H2'
)
SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY a.score) AS median_score
FROM skills.assessments a
JOIN cycle c ON a.cycle_id = c.cycle_id;"}

{"action": "sql", "sql": "WITH negotiation_skill AS (
  SELECT skill_id FROM skills.skills WHERE skill_name = 'Negotiation'
),
cycles_2025 AS (
  SELECT cycle_id FROM skills.assessment_cycles WHERE EXTRACT(YEAR FROM starts_on) = 2025
)
SELECT COUNT(DISTINCT a.employee_id) AS employee_count
FROM skills.assessments a
JOIN negotiation_skill ns ON a.skill_id = ns.skill_id
JOIN cycles_2025 c ON a.cycle_id = c.cycle_id;"}

{"action": "sql", "sql": "WITH cycle AS (
  SELECT cycle_id FROM skills.assessment_cycles WHERE cycle_name = '2025-H2'
),
assessments_in_cycle AS (
  SELECT assessor_id, assessment_id
  FROM skills.assessments
  WHERE cycle_id = (SELECT cycle_id FROM cycle)
)
SELECT ROUND(COUNT(assessment_id)::numeric / NULLIF(COUNT(DISTINCT assessor_id), 0), 2) AS avg_assessments_per_assessor
FROM assessments_in_cycle;"}
